import React from "react";

const ProductCard = ({ product }) => {
  return (
    <div className="border rounded-lg p-4 shadow-sm flex flex-col gap-2 bg-gray-50">
      <h2 className="font-bold text-lg">{product.title}</h2>
      <p className="text-sm text-gray-600">Stok: {product.stock}</p>
      <p className="text-sm">Fiyat (1-4): ${product.one_four_units}</p>
      <p className="text-sm">Fiyat (5-9): ${product.five_nine_units}</p>
      <p className="text-sm">Fiyat (10+): ${product.ten_plus_units}</p>
      <p className="text-xs text-gray-500">{product.description}</p>
      <div className="flex flex-wrap gap-1 mt-2">
        {product.bullet_1 && <span className="badge">{product.bullet_1}</span>}
        {product.bullet_2 && <span className="badge">{product.bullet_2}</span>}
        {product.bullet_3 && <span className="badge">{product.bullet_3}</span>}
        {product.bullet_4 && <span className="badge">{product.bullet_4}</span>}
      </div>
      <div className="flex gap-2 text-xs mt-2">
        <span>Renk: {product.color}</span>
        <span>Malzeme: {product.material_type}</span>
        <span>Boyut: {product.size}</span>
      </div>
    </div>
  );
};

export default ProductCard;
